package net.civeira.phylax.common.security;

import java.util.function.Function;

import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NonNull;

@Getter
@AllArgsConstructor
public abstract class AuthorizationDecision {

  @NonNull
  public final OperationContext context;

  @NonNull
  private Permission permission;

  public abstract String resourceName();

  public abstract String actionName();

  public Actor getActor() {
    return context.getActor();
  }

  public InvocationSource getSource() {
    return context.getSource();
  }

  public void map(Function<Permission, Permission> allowed) {
    permission = allowed.apply(permission);
  }

  public void deny() {
    this.permission = Permission.deny();
  }

  public void deny(String reason) {
    this.permission = Permission.deny(reason);
  }
}
